entries[264348] = { ["name"] = "Unbound Manawyrm", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\n\nSummons and dismisses the Unbound Manawyrm. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nRequires the completion of the Void Response Team and Ritual Site Disruptor Achievements.\n\n\"The turbulant void magics that have gripped the Sunwell are attracting the rare great manawyrms, corrupting them as they feed on the unbound magics.\"\nAchievement:\nVoid Response Team\nVendor:\nSergeant Vornin\nZone:\nSilvermoon City\nCost:\n6000" }
